const defaults=()=>({version:1,theme:'evjf',name:'Our hen party in Puglia',people:6,start:'',days:3,arrival:'Bari',budget:400,pace:'slow',transport:'driving',interests:['beach','food','party'],zone:null,plan:[],members:Array.from({length:6},(_,i)=>'Person '+(i+1)),expenses:[],notes:[],splitLink:''});
